package at.rabattradar.core.i18n

import at.rabattradar.core.model.CondKey
import at.rabattradar.core.model.Condition
import at.rabattradar.core.model.PriceTier
import at.rabattradar.core.model.SourceId
import at.rabattradar.core.model.TierKind
import java.time.DayOfWeek
import java.time.LocalDate
import java.util.Locale

enum class Lang { DE, EN }

/**
 * All user-facing text generated by the core library, in German and English.
 * Conditions and price tiers are stored as keys + arguments and rendered here, so the app can switch
 * language without re-scraping. Product names and descriptions come from the shops and stay German.
 */
object Texts {

    private fun Lang.pick(de: String, en: String) = if (this == Lang.DE) de else en

    fun money(v: Double, lang: Lang): String = String.format(if (lang == Lang.DE) Locale.GERMANY else Locale.UK, "%.2f", v)

    // --- Dates ------------------------------------------------------------------------------------------

    private val shortDe = listOf("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So")
    private val shortEn = listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
    private val longDe = listOf("Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag")
    private val longEn = listOf("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")

    private fun idx(d: DayOfWeek) = d.value - 1
    fun dayShort(d: LocalDate, lang: Lang) = (if (lang == Lang.DE) shortDe else shortEn)[idx(d.dayOfWeek)]
    fun dayLong(d: LocalDate, lang: Lang) = (if (lang == Lang.DE) longDe else longEn)[idx(d.dayOfWeek)]
    fun date(d: LocalDate) = "%02d.%02d.".format(d.dayOfMonth, d.monthValue)

    // --- Units ------------------------------------------------------------------------------------------

    /** German singular unit (as normalised by the parser) -> English singular / plural. */
    private val unitsEn = mapOf(
        "Tafel" to ("bar" to "bars"), "Pkg." to ("pack" to "packs"), "Fl." to ("bottle" to "bottles"),
        "Dose" to ("can" to "cans"), "Stk." to ("pc." to "pcs."), "Becher" to ("tub" to "tubs"), "Be." to ("tub" to "tubs"),
        "Beutel" to ("bag" to "bags"), "Glas" to ("jar" to "jars"), "Gl." to ("jar" to "jars"), "Karton" to ("carton" to "cartons"),
        "Tube" to ("tube" to "tubes"), "Rolle" to ("roll" to "rolls"), "Brief" to ("sachet" to "sachets"), "Box" to ("box" to "boxes"),
        "Paket" to ("pack" to "packs"), "Riegel" to ("bar" to "bars"), "Tasse" to ("cup" to "cups"), "Blister" to ("blister" to "blisters"),
        "Netz" to ("net" to "nets"), "Kiste" to ("crate" to "crates"), "Tray" to ("tray" to "trays"), "WG" to ("load" to "loads"),
        "Träger" to ("carrier" to "carriers"),
    )

    /** "Tafel" / "bar". */
    fun unitSingular(unit: String?, lang: Lang): String {
        val u = unit ?: "Stk."
        return if (lang == Lang.DE) u else unitsEn[u]?.first ?: u
    }

    private val packText = Regex("""(?:(\d+) x )?(\d+)er-(\S+)""")
    private val packsEn = mapOf(
        "Tray" to ("tray" to "trays"), "Träger" to ("carrier" to "carriers"), "Kiste" to ("crate" to "crates"),
        "Karton" to ("carton" to "cartons"), "Pack" to ("pack" to "packs"), "Packung" to ("pack" to "packs"),
    )

    /** Printed pack: "6er-Tray" / "tray of 6", "2 x 12er-Tray" / "2 trays of 12". */
    fun pack(printed: String, lang: Lang): String {
        if (lang == Lang.DE) return printed
        val m = packText.matchEntire(printed) ?: return printed
        val count = m.groupValues[1].toIntOrNull() ?: 1
        val (one, many) = packsEn[m.groupValues[3]] ?: (m.groupValues[3] to m.groupValues[3])
        return if (count == 1) "$one of ${m.groupValues[2]}" else "$count $many of ${m.groupValues[2]}"
    }

    /** "Tafeln" (as printed) / "bars". */
    fun unitPlural(unit: String?, printed: String?, lang: Lang): String {
        val u = unit ?: "Stk."
        return if (lang == Lang.DE) printed ?: u else unitsEn[u]?.second ?: printed ?: u
    }

    // --- Conditions ---------------------------------------------------------------------------------------

    private fun Condition.arg(k: String) = args[k]
    private fun Condition.price(k: String = "price") = args[k]?.toDoubleOrNull()

    fun label(c: Condition, lang: Lang): String = when (c.key) {
        CondKey.LIDL_PLUS -> "Lidl Plus"
        CondKey.SPAR_APP -> lang.pick("SPAR App", "SPAR app")
        CondKey.PENNY_APP -> lang.pick("PENNY App", "PENNY app")
        CondKey.BILLA_APP -> lang.pick("BILLA App", "BILLA app")
        CondKey.JOE -> "jö"
        CondKey.LOYALTY_GENERIC -> lang.pick("Kundenkarte", "Loyalty card")
        CondKey.APP_GENERIC -> "App"
        CondKey.MULTI_BUY -> "${c.arg("buy")}+${c.arg("free")} " + lang.pick("gratis", "free") + if (c.inferred) "?" else ""
        CondKey.MIN_QUANTITY -> {
            val n = c.quantity ?: 0
            val units = unitPlural(c.unit, c.arg("printed"), lang)
            if (c.arg("set") == "true") lang.pick("bei $n $units", "buy $n $units") else lang.pick("ab $n $units", "from $n $units")
        }
        CondKey.WEEKDAYS -> {
            val from = LocalDate.parse(c.arg("from"))
            val to = LocalDate.parse(c.arg("to"))
            val days = to.toEpochDay() - from.toEpochDay() + 1
            val range = when (days) {
                1L -> dayShort(from, lang)
                2L -> "${dayShort(from, lang)} & ${dayShort(to, lang)}"
                else -> "${dayShort(from, lang)}–${dayShort(to, lang)}"
            }
            lang.pick("nur $range", "$range only")
        }
        CondKey.ONLINE_ONLY -> lang.pick("nur online", "online only")
        CondKey.ONLINE_SHOP -> if (c.arg("store") == "BILLA") lang.pick("lt. Online-Shop", "per online shop") else lang.pick("Online-Shop", "Online shop")
        CondKey.CLEARANCE -> lang.pick("Abverkauf", "Clearance")
        CondKey.SATTER_RABATT -> "Satter Rabatt"
        CondKey.WEIGHT_PRICE -> lang.pick("Preis pro kg", "Price per kg")
        CondKey.VARIANTS -> lang.pick("versch. Sorten", "various kinds")
        CondKey.DEPOSIT -> {
            val amount = c.price("amount")
            when {
                amount == null -> lang.pick("+ Mehrwegpfand", "+ returnable deposit")
                else -> "+ ${money(amount, lang)}" + lang.pick(" Pfand", " deposit") + if (c.inferred) "?" else ""
            }
        }
        CondKey.NO_DATES -> lang.pick("Datum unbekannt", "Dates unknown")
        CondKey.FOOTNOTE -> lang.pick("Fußnote *", "Footnote *")
        CondKey.CAMPAIGN -> c.arg("name").orEmpty()
        CondKey.ALSO_ONLINE -> lang.pick("auch online", "also online")
        CondKey.DATES_ADOPTED -> lang.pick("Zeitraum übernommen", "Dates adopted")
        CondKey.WITHOUT_DEAL -> lang.pick("ohne ", "without ") + "${program(c.arg("program"), lang)}: " + quantityDeal(c, lang)
    }

    /** "4+2 gratis" or "bei 6 Fl." for a deal kept in a note. */
    private fun quantityDeal(c: Condition, lang: Lang): String {
        if (c.arg("buy") != null) return "${c.arg("buy")}+${c.arg("free")} " + lang.pick("gratis", "free")
        val units = unitPlural(c.unit, c.arg("printed"), lang)
        val n = c.quantity ?: 0
        return if (c.arg("set") == "true") lang.pick("bei $n $units", "buy $n $units") else lang.pick("ab $n $units", "from $n $units")
    }

    fun detail(c: Condition, lang: Lang): String? = when (c.key) {
        CondKey.LIDL_PLUS -> buildString {
            if (c.arg("exclusive") == "true") {
                append(lang.pick("Lidl Plus exklusiv – ohne Lidl Plus App gibt es diesen Aktionspreis nicht.", "Lidl Plus exclusive – without the Lidl Plus app there is no promotional price."))
            } else {
                append(lang.pick("Preis nur mit der Lidl Plus App (Coupon in der App aktivieren und an der Kassa scannen).", "Price only with the Lidl Plus app (activate the coupon in the app and scan it at the till)."))
                c.price()?.let { append(lang.pick(" Mit Lidl Plus: ${money(it, lang)} €.", " With Lidl Plus: €${money(it, lang)}.")) }
            }
            c.arg("highlight")?.let { append(lang.pick(" Vorteil laut Lidl: $it.", " Saving according to Lidl: $it.")) }
        }
        CondKey.SPAR_APP -> lang.pick("Preis nur mit Gutschein aus der SPAR App (Gutschein vorher aktivieren).", "Price only with a voucher from the SPAR app (activate it beforehand).") +
            (c.price()?.let { lang.pick(" Mit Gutschein: ${money(it, lang)} €.", " With voucher: €${money(it, lang)}.") } ?: "")
        CondKey.PENNY_APP -> lang.pick("Preis nur mit der PENNY App bzw. jö Karte.", "Price only with the PENNY app or the jö card.") +
            (c.price()?.let { lang.pick(" Mit App/jö: ${money(it, lang)} €.", " With app/jö: €${money(it, lang)}.") } ?: "")
        CondKey.BILLA_APP -> lang.pick("Preis nur mit Coupon aus der BILLA App.", "Price only with a coupon from the BILLA app.")
        CondKey.JOE -> lang.pick(
            "Preis nur für Mitglieder des jö Bonus Clubs (jö Karte oder jö App an der Kassa vorzeigen)",
            "Price only for members of the jö Bonus Club (show the jö card or app at the till)",
        ) + (if (c.arg("chain") == "PENNY") lang.pick(" bzw. mit der PENNY App.", " or with the PENNY app.") else ".") +
            (c.price()?.let { lang.pick(" jö-Preis: ${money(it, lang)} €.", " jö price: €${money(it, lang)}.") } ?: "")
        CondKey.LOYALTY_GENERIC -> lang.pick("Preis nur mit Kundenkarte/App des Händlers.", "Price only with the store's loyalty card or app.")
        CondKey.APP_GENERIC -> lang.pick("Preis nur mit der App des Händlers.", "Price only with the store's app.")
        CondKey.MULTI_BUY -> {
            val buy = c.arg("buy")?.toIntOrNull() ?: 0
            val free = c.arg("free")?.toIntOrNull() ?: 0
            if (c.inferred) {
                val regular = c.price("regular")?.let { money(it, lang) } ?: "?"
                lang.pick(
                    "Der Preis entspricht genau 2/3 des Normalpreises ($regular €). Im Flugblatt steht dann meist „2+1 gratis“ (oder „4+2 gratis“) – " +
                        "der Preis gilt nur beim Kauf von 3 (bzw. 6) Stück. Die Datenquelle nennt die Bedingung nicht, bitte im Flugblatt prüfen.",
                    "The price is exactly 2/3 of the normal price (€$regular). The flyer then usually says \"2+1 free\" (or \"4+2 free\") – " +
                        "the price only applies when buying 3 (or 6). The data source does not state the condition, please check the flyer.",
                )
            } else {
                lang.pick(
                    "Beim Kauf von ${buy + free} Stück sind $free gratis. Der Aktionspreis je Stück gilt nur, wenn ${buy + free} (oder ein Vielfaches) gekauft werden.",
                    "Buy ${buy + free}, get $free free. The promotional price per item only applies when buying ${buy + free} (or a multiple).",
                )
            }
        }
        CondKey.MIN_QUANTITY -> {
            val n = c.quantity ?: 0
            val one = unitSingular(c.unit, lang)
            val units = unitPlural(c.unit, c.arg("printed"), lang)
            if (c.arg("set") == "true") {
                lang.pick(
                    "Aktionspreis je $one gilt nur beim Kauf von $n $units (bzw. einem Vielfachen davon). Einzeln gilt der Normalpreis.",
                    "The promotional price per $one only applies when buying $n $units (or a multiple). A single item costs the normal price.",
                )
            } else {
                lang.pick(
                    "Aktionspreis je $one gilt ab dem Kauf von $n $units. Einzeln gilt der Normalpreis.",
                    "The promotional price per $one applies from $n $units. A single item costs the normal price.",
                )
            }
        }
        CondKey.WEEKDAYS -> {
            val from = LocalDate.parse(c.arg("from"))
            val to = LocalDate.parse(c.arg("to"))
            if (from == to) {
                lang.pick("Aktion gilt nur am ${dayLong(from, lang)}, ${date(from)}", "Only valid on ${dayLong(from, lang)}, ${date(from)}")
            } else {
                lang.pick(
                    "Aktion gilt nur von ${dayLong(from, lang)}, ${date(from)} bis ${dayLong(to, lang)}, ${date(to)}",
                    "Only valid from ${dayLong(from, lang)}, ${date(from)} to ${dayLong(to, lang)}, ${date(to)}",
                )
            }
        }
        CondKey.ONLINE_ONLY -> lang.pick("Nur im Online-Shop erhältlich, nicht in der Filiale.", "Only available in the online shop, not in stores.")
        CondKey.ONLINE_SHOP -> if (c.arg("store") == "BILLA") {
            lang.pick("Preis aus dem BILLA Online-Shop – in der Filiale kann er abweichen.", "Price from the BILLA online shop – it may differ in stores.")
        } else {
            lang.pick("Aktion im INTERSPAR Online-Shop – in der Filiale können Preis und Sortiment abweichen.", "Promotion in the INTERSPAR online shop – price and range may differ in stores.")
        }
        CondKey.CLEARANCE -> lang.pick("Abverkaufsware – nur solange der Vorrat reicht.", "Clearance item – while stocks last.")
        CondKey.SATTER_RABATT -> lang.pick("Aktion „Satter Rabatt“ laut ${c.arg("banner")}.", "\"Satter Rabatt\" promotion according to ${c.arg("banner")}.")
        CondKey.WEIGHT_PRICE -> lang.pick("Preis gilt pro Kilogramm – der Endpreis hängt vom Gewicht ab.", "Price per kilogram – the final price depends on the weight.")
        CondKey.VARIANTS -> lang.pick(
            "Der Preis gilt für mehrere Sorten/Varianten – nicht jede Sorte ist in jeder Filiale erhältlich.",
            "The price applies to several kinds/variants – not every kind is available in every store.",
        )
        CondKey.DEPOSIT -> depositDetail(c, lang)
        CondKey.NO_DATES -> if (c.arg("store") == "BILLA") {
            lang.pick(
                "Der BILLA Online-Shop nennt keinen Aktionszeitraum. BILLA-Wochenaktionen laufen meist von Donnerstag bis Mittwoch.",
                "The BILLA online shop gives no promotion period. BILLA weekly deals usually run Thursday to Wednesday.",
            )
        } else {
            lang.pick("Der Online-Shop nennt keinen Aktionszeitraum.", "The online shop gives no promotion period.")
        }
        CondKey.FOOTNOTE -> lang.pick(
            "Im Flugblatt mit * markiert – es gilt eine Fußnote (z. B. nicht in allen Filialen, Pfand, keine weiteren Rabatte). Details im Flugblatt.",
            "Marked with * in the flyer – a footnote applies (e.g. not in all stores, deposit, no further discounts). See the flyer.",
        )
        CondKey.CAMPAIGN -> lang.pick("Teil der Aktion „${c.arg("name")}“.", "Part of the \"${c.arg("name")}\" promotion.")
        CondKey.ALSO_ONLINE -> lang.pick(
            "Auch im Lidl Online-Shop erhältlich (Online-Preise und Versandkosten können abweichen).",
            "Also available in the Lidl online shop (online prices and shipping costs may differ).",
        )
        CondKey.DATES_ADOPTED -> lang.pick(
            "Aktionszeitraum vom gleichartigen Flugblatt-Angebot „${c.arg("name")}“ übernommen (gleiche Marke, gleicher Preis, gleiche Bedingung).",
            "Promotion period taken from the similar flyer offer \"${c.arg("name")}\" (same brand, price and condition).",
        )
        CondKey.WITHOUT_DEAL -> {
            val n = c.quantity ?: 0
            val units = unitPlural(c.unit, c.arg("printed"), lang)
            val price = c.price()?.let { money(it, lang) } ?: "?"
            val program = program(c.arg("program"), lang)
            val free = c.arg("buy")?.let { lang.pick(" (${it}+${c.arg("free")} gratis)", " (${it}+${c.arg("free")} free)") }.orEmpty()
            lang.pick(
                "Der angezeigte Preis gilt mit $program. Ohne $program gibt es laut Flugblatt eine Mengenaktion: " +
                    "${if (c.arg("set") == "true") "bei" else "ab"} $n $units je $price €$free.",
                "The price shown needs the $program. Without it, the flyer offers a multi-buy: " +
                    "${if (c.arg("set") == "true") "buy" else "from"} $n $units at €$price each$free.",
            )
        }
    }

    private fun depositDetail(c: Condition, lang: Lang): String = buildString {
        val amount = c.price("amount")
        val containers = c.arg("containers")?.toIntOrNull() ?: 1
        val reusable = c.arg("kind") == "REUSABLE"
        val what = if (reusable) lang.pick("Mehrwegpfand", "Returnable deposit") else lang.pick("Einwegpfand", "Single-use deposit")
        if (amount != null) {
            append("$what: ")
            if (containers > 1) append("$containers × ${money(amount / containers, lang)} ${lang.pick("€", "EUR")} = ")
            append(lang.pick("${money(amount, lang)} € – wird an der Kassa zusätzlich verrechnet und bei Rückgabe erstattet. ", "€${money(amount, lang)} – charged at the till and refunded when you return the container. "))
            c.price("total")?.let { append(lang.pick("Preis inkl. Pfand: ${money(it, lang)} €.", "Price incl. deposit: €${money(it, lang)}.")) }
        } else {
            append(lang.pick("$what – die Höhe nennt die Quelle nicht (Flaschen und Kisten haben eigene Pfandbeträge).", "$what – the source does not state the amount (bottles and crates have their own deposits)."))
        }
        if (c.inferred) {
            append(lang.pick(" Vermutet anhand von Getränkeart, Verpackung und Füllmenge – bitte im Flugblatt prüfen.", " Inferred from drink type, container and volume – please check the flyer."))
        }
    }

    // --- Price tiers ----------------------------------------------------------------------------------------

    private fun program(p: String?, lang: Lang) = when (p) {
        "voucher" -> lang.pick("Gutschein", "voucher")
        "app" -> lang.pick("App", "app")
        null -> lang.pick("App", "app")
        else -> p
    }

    fun tier(t: PriceTier, lang: Lang): String = when (t.kind) {
        TierKind.SINGLE -> if (t.unit == null) lang.pick("Einzeln", "Single") else "1 ${unitSingular(t.unit, lang)}"
        TierKind.WITHOUT -> lang.pick("ohne ${program(t.program, lang)}", "without ${program(t.program, lang)}")
        TierKind.LOWEST_30_DAYS -> lang.pick("Bestpreis 30 Tage", "Lowest price (30 days)")
    }

    // --- Sources ------------------------------------------------------------------------------------------------

    fun sourceName(s: SourceId, lang: Lang): String = when (s) {
        SourceId.MARKTGURU -> "marktguru.at"
        SourceId.BILLA_SHOP -> lang.pick("BILLA Online-Shop", "BILLA online shop")
        SourceId.LIDL_WEB -> "lidl.at"
        SourceId.PENNY_WEB -> "penny.at"
        SourceId.SPAR_SHOP -> lang.pick("INTERSPAR Online-Shop", "INTERSPAR online shop")
        SourceId.BILLA_FLYER -> lang.pick("BILLA Flugblatt (Text)", "BILLA flyer (text)")
        SourceId.SPAR_FLYER -> lang.pick("SPAR Flugblatt (Text)", "SPAR flyer (text)")
    }

    fun sourceDescription(s: SourceId, lang: Lang): String = when (s) {
        SourceId.MARKTGURU -> lang.pick("Flugblatt-Angebote (alle Ketten, inkl. HOFER)", "Flyer offers (all chains, incl. HOFER)")
        SourceId.BILLA_SHOP -> lang.pick("Strukturierte Aktionen inkl. Mengenrabatte, aber ohne Gültigkeitsdatum", "Structured promotions incl. multi-buys, but without dates")
        SourceId.LIDL_WEB -> lang.pick("Filial-Angebote mit Lidl Plus Preisen und exakten Aktionstagen", "In-store offers with Lidl Plus prices and exact dates")
        SourceId.PENNY_WEB -> lang.pick("Wochenangebote mit jö/App-Preisen und Mengenrabatten", "Weekly offers with jö/app prices and multi-buys")
        SourceId.SPAR_SHOP -> lang.pick("Online-Shop-Aktionen (meist Non-Food und Getränke)", "Online shop promotions (mostly non-food and drinks)")
        SourceId.BILLA_FLYER -> lang.pick("Mengenaktionen wie 3+3 gratis aus dem Text des BILLA/BILLA PLUS Flugblatts", "Multi-buys like 3+3 free from the text of the BILLA/BILLA PLUS flyer")
        SourceId.SPAR_FLYER -> lang.pick("Mengenaktionen wie 12+12 gratis und Tray-Preise aus den SPAR/EUROSPAR/INTERSPAR-Flugblättern", "Multi-buys like 12+12 free and tray prices from the SPAR/EUROSPAR/INTERSPAR flyers")
    }
}
